import fs from "node:fs";

function d(value) { return Buffer.from(value, "base64").toString("utf8"); }
function replaceOnce(path, oldB64, newB64) {
  const oldText = d(oldB64);
  const newText = d(newB64);
  const source = fs.readFileSync(path, "utf8");
  const first = source.indexOf(oldText);
  if (first < 0) throw new Error(`Expected patch anchor not found in ${path}: ${oldText.slice(0, 100)}`);
  if (source.indexOf(oldText, first + oldText.length) >= 0) throw new Error(`Patch anchor is not unique in ${path}`);
  fs.writeFileSync(path, source.slice(0, first) + newText + source.slice(first + oldText.length));
}

